package com.yeyamo_mobile.api.notification_service.infrastructure.template;
import java.util.Map;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.TemplatePort;import com.yeyamo_mobile.api.notification_service.domain.*;import com.yeyamo_mobile.api.notification_service.infrastructure.persistence.*;
@Component public class JpaTemplateAdapter implements TemplatePort{private final SpringTemplateRepository repo;public JpaTemplateAdapter(SpringTemplateRepository r){repo=r;}public RenderedTemplate render(String event,NotificationChannel channel,String locale,Map<String,String>vars){TemplateEntity t=repo.findByEventTypeAndChannelAndLocaleAndActiveTrue(event,channel,locale).or(()->repo.findByEventTypeAndChannelAndLocaleAndActiveTrue(event,channel,"fr")).or(()->repo.findByEventTypeAndChannelAndLocaleAndActiveTrue("default",channel,locale)).or(()->repo.findByEventTypeAndChannelAndLocaleAndActiveTrue("default",channel,"fr")).orElseThrow(()->new IllegalStateException("No notification template for "+event+"/"+channel));return new RenderedTemplate(fill(t.getSubjectTemplate()==null?"YeYamo":t.getSubjectTemplate(),vars),fill(t.getBodyTemplate(),vars));}private String fill(String value,Map<String,String>vars){String result=value;for(var e:vars.entrySet())result=result.replace("{{"+e.getKey()+"}}",e.getValue()==null?"":e.getValue());return result.replaceAll("\\{\\{[^}]+}}","");}}
